<?php if ( ! defined('BASEPATH')) exit('No direct script access allowed');class mbom extends CI_Controller {    public function __construct() {        parent::__construct();        fnIfCheckUserLoggedIn();        $this->load->model(CNFCOMPANY."mbommodel");        $this->load->helper('xssclean');        $this->limit = LIMITPERPAGE;    }    public function addedit() {        $ArrData = array('ArrBasicInfo' => array(), 'VarId' => '');        $VarId		    									    = $this->uri->segment(4);        $ArrData['Edit'] = $this->uri->segment(5);        if($VarId<>'' && base64_decode(urldecode($VarId))) {            $VarUserId                                          = base64_decode(urldecode($VarId));            $ArrResults     									= $this->mbommodel->fnGetInfo('','',$VarUserId);            $ArrData['ArrBasicInfo']	    				    = $ArrResults[0];            $ArrData['VarId']					                = $ArrResults[0]['id'];        } else {        }        $this->load->view(CNFCOMPANY.'addeditbom',$ArrData);    }    public function updateInfo() {        $VarUserInfo                                        = fnGetUserLoggedInfo(1);        $VarCompanyId                                       = $VarUserInfo['companyid'];        $VarIDesc				    						= xssclean($this->input->post('i'));        $VarBlend				    						= xssclean($this->input->post('b'));        $VarSpl				    						    = xssclean($this->input->post('spl'));        $VarContent                                         = xssclean($this->input->post('cn'));        $VarMat                                             = xssclean($this->input->post('ma'));        $VarArtType                                         = xssclean($this->input->post('arttype'));        $VarStatus											= xssclean($this->input->post('s'));        $VarId       										= xssclean($this->input->post('id'));        if($VarIDesc<>'') {            $ArrUpdateData                                      = array('id'=>$VarId,'articletype'=>$VarArtType,'companyid'=>$VarCompanyId,                'bomitemdesc'=>$VarIDesc,'bomblend'=>$VarBlend,'bomsplreq'=>$VarSpl,'content'=>$VarContent,'material'=>$VarMat,                'status'=>$VarStatus,'updatedby'=>$VarUserInfo['id'],'dateupdated'=>date('Y-m-d H:i:s'));            if($VarId=='' || $VarId==0) {                $ArrUpdateData['datecreated']                   = date('Y-m-d H:i:s');            }            $ArrResult = $this->mbommodel->saveInfo($ArrUpdateData);        }        else {            $ArrResult['errcode'] = -1;            $ArrResult['msg']								    = 'Invalid Input!';        }        echo json_encode($ArrResult);    }    public function manage() {        $VarFrom												= xssclean($this->input->post('rfrom'));        $VarName = xssclean($this->input->post('i'));        $VarContent											    = xssclean($this->input->post('c'));        $VarBlend											    = xssclean($this->input->post('b'));        $Varmaterial											    = xssclean($this->input->post('m'));        $VarSpecial = xssclean($this->input->post('spl'));        $VarArtType											= xssclean($this->input->post('arttype'));        $VarStatus  											= xssclean($this->input->post('s'));        $clickedColumnId  										= xssclean($this->input->post('columnId'));        $newsortorder  										    = xssclean($this->input->post('sortorder'));        $VarAfilter  										    = xssclean($this->input->post('afilter'));        $ArrDbCols = array('b.bomitemdesc', 'b.bomblend', 'b.content', 'b.articletype', 'b.material', 'b.bomsplreq', 'b.status', 'u.contactname', 'b.dateupdated');        $ArrStatus = unserialize(ARRSTATUS);        if($VarFrom==1) {            $VarURLSegment										= 4;            $this->load->library('pagination');            $config['base_url']									= base_url().CNFCOMPANY.'mbom/manage/';            $config['total_rows']								= $this->mbommodel->fnCount($VarName,$VarContent,$VarStatus,$VarBlend,                $VarArtType,$Varmaterial,$VarSpecial,$VarAfilter);            $config['per_page']									= $this->limit;            $config['uri_segment']								= $VarURLSegment;            $offset												= $this->uri->segment($VarURLSegment);            $this->pagination->initialize($config);            $sortby												= "dateupdated";            $sortorder											= "desc";            if($clickedColumnId <> '' && $newsortorder <> '') {                if(array_key_exists($clickedColumnId,$ArrDbCols)) {                    $sortby = $ArrDbCols[$clickedColumnId];                }                $sortorder = $newsortorder;            }            $ArrList								    = $this->mbommodel->fnList($VarName,$VarContent,$VarStatus,$VarBlend,$VarArtType,                $Varmaterial,$VarSpecial,$this->limit,$offset,$sortby,$sortorder,$VarAfilter)->result();            $data['pagination']									= $this->pagination->create_linkswithajax('Bom');            $i=0;            $ArrFnlList										    = array();            foreach ($ArrList as $ObjRes) {                $ArrFnlList[$i]['id']						    = $ObjRes->id;                $ArrFnlList[$i]['i']						    = $ObjRes->bomitemdesc;                $ArrFnlList[$i]['arttype']						= $ObjRes->articletype;                $ArrFnlList[$i]['c']						    = $ObjRes->content;                $ArrFnlList[$i]['m']						    = $ObjRes->material;                $ArrFnlList[$i]['spl']						    = $ObjRes->bomsplreq;                $ArrFnlList[$i]['b']						    = $ObjRes->bomblend;                $ArrFnlList[$i]['ub']						    = $ObjRes->contactname;                $ArrFnlList[$i]['s']						    = $ArrStatus[$ObjRes->status];                $ArrFnlList[$i]['du']						    = date('d-m-Y H:i A',strtotime($ObjRes->dateupdated));                $i=$i+1;            }            echo json_encode(array('errcode'=>1,'cn'=>$config['total_rows'],'ct'=>$i,'re'=>$ArrFnlList,'pa'=>base64_encode($data['pagination'])));            unset($ArrFnlList);            die;        } else {            $this->load->view(CNFCOMPANY . 'managebom', array('ArrStatus' => $ArrStatus));        }    }    function changemStatus() {        $VarRfrom 	   										    = xssclean($this->input->post('rfrom'));        if($VarRfrom == 1) {            $VarActDeactOption										= xssclean($this->input->post('actdeactFabType'));            $VarCid 	   										    = xssclean($this->input->post('cid'));            if($VarActDeactOption <> '' && $VarCid <> '') {                $this->mbommodel->fnChangeComStat($VarCid,$VarActDeactOption);            }            echo json_encode(array('errcode'=> 1));            die;        }    }}